// Expected Goal: Trapped Water: 6

import java.util.*;

public class Main {
    public static void main(String[] args) {
        int[] height = {0, 1, 0, 2, 1, 0, 1, 3, 2, 1, 2, 1};

        // TODO: Write your code below to solve this problem:

    }
}

